#!/usr/bin/env python3
"""Read-only transcript scanner for /doctor. Aggregates usage, hook timings, denials."""
import json, glob, os, re, sys
from collections import Counter, defaultdict

PROJ = os.path.expanduser("~/.agent/projects")
files = glob.glob(os.path.join(PROJ, "*", "*.jsonl"))
files.sort(key=lambda f: os.path.getmtime(f), reverse=True)
files = files[:50]

skill_uses = Counter()          # Skill tool_use input.skill
cmd_invocations = Counter()     # <command-name> user entries
mcp_calls = Counter()           # mcp__server__tool
mcp_servers = Counter()         # normalized server segment
hook_stats = defaultdict(list)  # (hookName, hookEvent) -> [durationMs]
hook_timeouts = Counter()       # (hookName, hookEvent) -> timedout count
denials = Counter()             # (key, kind) -> count
denial_examples = defaultdict(set)  # key -> set of full commands (bash) capped
ts_min, ts_max = None, None
cmdname_re = re.compile(r"<command-name>/?([^<]{1,80})</command-name>")

DENY_TEXTS = ("The user doesn't want to proceed with this tool use",)
DENY_PREFIXES = ("Permission to use", "Permission for this")

def bash_key(cmd):
    if not isinstance(cmd, str):
        return "Bash(?)"
    s = cmd.strip()
    toks = s.split()
    if not toks:
        return "Bash(?)"
    # keep first two tokens; flag env-prefix / compound forms distinctly
    first = toks[0]
    if "=" in first:
        return f"Bash(ENVPREFIX {first.split('=')[0]}=...)"
    key = first
    if len(toks) > 1 and re.match(r"^[a-zA-Z0-9_.-]+$", toks[1]):
        key += " " + toks[1]
    return key

for fp in files:
    tool_use_map = {}  # id -> (name, key, full_cmd)
    try:
        fh = open(fp, "r", errors="replace")
    except OSError:
        continue
    with fh:
        for line in fh:
            try:
                obj = json.loads(line)
            except Exception:
                continue
            ts = obj.get("timestamp")
            if isinstance(ts, str) and len(ts) >= 10:
                if ts_min is None or ts < ts_min: ts_min = ts
                if ts_max is None or ts > ts_max: ts_max = ts
            t = obj.get("type")
            if t == "assistant":
                msg = obj.get("message") or {}
                for item in (msg.get("content") or []):
                    if not isinstance(item, dict) or item.get("type") != "tool_use":
                        continue
                    name = item.get("name", "")
                    inp = item.get("input") or {}
                    full = None
                    if name == "Skill":
                        sk = inp.get("skill")
                        if isinstance(sk, str): skill_uses[sk[:80]] += 1
                    if name.startswith("mcp__"):
                        mcp_calls[name[:120]] += 1
                        parts = name.split("__")
                        if len(parts) >= 2: mcp_servers[parts[1][:80]] += 1
                    if name == "Bash":
                        full = inp.get("command")
                        key = "Bash: " + bash_key(full)
                    else:
                        key = name[:120]
                    tid = item.get("id")
                    if tid:
                        tool_use_map[tid] = (name, key, full if isinstance(full, str) else None)
            elif t == "user":
                kind = obj.get("toolDenialKind")
                msg = obj.get("message") or {}
                content = msg.get("content")
                # command-name invocations
                if isinstance(content, str):
                    for m in cmdname_re.finditer(content):
                        cmd_invocations[m.group(1)] += 1
                elif isinstance(content, list):
                    for item in content:
                        if not isinstance(item, dict):
                            continue
                        if item.get("type") == "text" and isinstance(item.get("text"), str):
                            for m in cmdname_re.finditer(item["text"]):
                                cmd_invocations[m.group(1)] += 1
                        if item.get("type") == "tool_result":
                            tid = item.get("tool_use_id")
                            ref = tool_use_map.get(tid)
                            fb_kind = None
                            if kind is None and item.get("is_error"):
                                tc = item.get("content")
                                txt = ""
                                if isinstance(tc, str): txt = tc
                                elif isinstance(tc, list):
                                    txt = " ".join(x.get("text", "") for x in tc if isinstance(x, dict))
                                if any(d in txt for d in DENY_TEXTS) or txt.startswith(DENY_PREFIXES):
                                    fb_kind = "text-fallback(unverified)"
                            eff = kind or fb_kind
                            if eff and ref:
                                name, key, full = ref
                                if eff == "text-fallback(unverified)" and name.startswith("mcp__"):
                                    continue  # never text-match MCP denials
                                denials[(key, eff)] += 1
                                if full and len(denial_examples[key]) < 8:
                                    denial_examples[key].add(full[:200])
            elif t == "attachment":
                att = obj.get("attachment") or {}
                at = att.get("type", "")
                if at.startswith("hook_"):
                    hn = str(att.get("hookName", "?"))[:80]
                    he = str(att.get("hookEvent", "?"))[:40]
                    dur = att.get("durationMs")
                    if at == "hook_cancelled":
                        if att.get("timedOut"):
                            hook_timeouts[(hn, he)] += 1
                            d = att.get("timeoutMs") or dur
                            if isinstance(d, (int, float)): hook_stats[(hn, he)].append(float(d))
                    elif isinstance(dur, (int, float)):
                        hook_stats[(hn, he)].append(float(dur))

def pct(v, p):
    if not v: return 0
    v = sorted(v); i = min(len(v) - 1, int(len(v) * p))
    return v[i]

out = {
    "files_scanned": len(files),
    "window": [ts_min, ts_max],
    "skill_uses": dict(skill_uses.most_common()),
    "command_invocations": dict(cmd_invocations.most_common(60)),
    "mcp_calls": dict(mcp_calls.most_common(40)),
    "mcp_servers": dict(mcp_servers.most_common()),
    "hooks": {
        f"{hn} @{he}": {"runs": len(v), "median_ms": round(pct(v, 0.5)), "p90_ms": round(pct(v, 0.9)),
                         "max_ms": round(max(v)), "timeouts": hook_timeouts.get((hn, he), 0)}
        for (hn, he), v in sorted(hook_stats.items(), key=lambda kv: -pct(kv[1], 0.5))
    },
    "hook_timeout_only": {f"{k[0]} @{k[1]}": c for k, c in hook_timeouts.items() if (k not in hook_stats)},
    "denials": [{"key": k, "kind": kd, "count": c} for (k, kd), c in denials.most_common(40)],
    "denial_examples": {k: sorted(v) for k, v in list(denial_examples.items())[:40]},
}
json.dump(out, sys.stdout, indent=1)
print()

