examples = defaultdict(set)
for fp in files:
    proj = os.path.basename(os.path.dirname(fp))
    tum = {}
    with open(fp, errors="replace") as fh:
        for line in fh:
            try: obj = json.loads(line)
            except Exception: continue
            t = obj.get("type")
            if t == "assistant":
                for it in ((obj.get("message") or {}).get("content") or []):
                    if isinstance(it, dict) and it.get("type") == "tool_use" and it.get("id"):
                        tum[it["id"]] = (it.get("name"), (it.get("input") or {}).get("command"))
            elif t == "user":
                kind = obj.get("toolDenialKind")
                if kind:
                    c = (obj.get("message") or {}).get("content")
                    if isinstance(c, list):
                        for it in c:
                            if isinstance(it, dict) and it.get("type") == "tool_result":
                                ref = tum.get(it.get("tool_use_id"))
                                if ref and ref[0] == "Bash" and isinstance(ref[1], str):
                                    head = ref[1].strip().split()[0] if ref[1].strip() else "?"
                                    if head in ("gh", "cd", "aws") or head.startswith("tail"):
                                        if len(examples[head]) < 12:
                                            examples[head].add(f"[{kind}] {ref[1][:160]}")
            elif t == "attachment":
                a = obj.get("attachment") or {}
                if a.get("type", "").startswith("hook_") and a.get("hookEvent") == "UserPromptSubmit":
                    per_proj[proj]["runs"] += 1
                    if a.get("type") == "hook_cancelled" and a.get("timedOut"):
                        per_proj[proj]["timeouts"] += 1
