    except OSError: return None
    m = re.match(r"^---\s*\n(.*?)\n---", txt, re.S)
    if not m: return {}
    d = {}
    for line in m.group(1).splitlines():
        mm = re.match(r"^(name|description)\s*:\s*(.*)$", line)
        if mm: d[mm.group(1)] = mm.group(2).strip()
    return d
groups = {
